/**
 * Default Level 1 order maps:
 * T -> slot 0 (Red), L -> slot 1 (Blue), I -> slot 2 (Cyan),
 * O -> slot 3 (Yellow), S -> slot 4 (Green), Z -> slot 5 (Purple), J -> slot 6 (Orange)
 */
const LEVEL_1_ORDER = Object.freeze(['T', 'L', 'I', 'O', 'S', 'Z', 'J']);

/**
 * Standard Guideline mapping (when user disables per-level color randomization)
 */
const GUIDELINE_ORDER = Object.freeze(['Z', 'J', 'I', 'O', 'S', 'T', 'L']);

/**
 * Generates a map of { I, O, T, S, Z, J, L } -> hex color for a given level.
 * - Each of the 7 pieces ALWAYS receives a unique color from the 7-color palette.
 * - Level 1 assigns T=Red (slot 0) and L=Blue (slot 1).
 * - Each subsequent level (level >= 2) randomly shuffles the assignment so every new level
 *   has a fresh random color arrangement, guaranteed to differ from the previous level map.
 */
function generateLevelColorMap({
  level = 1,
  theme = 'neon',
  colorblind = false,
  randomLevelColors = true,
  previousMap = null,
  seed = null,
} = {}) {
  const paletteKey = colorblind ? 'colorblind' : (THEME_PALETTES[theme] ? theme : 'neon');
  const palette = THEME_PALETTES[paletteKey];

  if (!randomLevelColors) {
    const map = {};
    GUIDELINE_ORDER.forEach((type, idx) => {
      map[type] = palette[idx];
    });
    return map;
  }

  if (level <= 1 && !previousMap) {
    const map = {};
    LEVEL_1_ORDER.forEach((type, idx) => {
      map[type] = palette[idx];
    });
    return map;
  }

  // Deterministic or random shuffle for level >= 2
  const rng = seed !== null ? createRNG(seed + level * 7919) : Math.random;
  const indices = [0, 1, 2, 3, 4, 5, 6];
  shuffleArray(indices, rng);

  // Ensure at least T and L (and overall mapping) changed compared to previousMap
  if (previousMap) {
    let allSame = LEVEL_1_ORDER.every((type, i) => previousMap[type] === palette[indices[i]]);
    if (allSame || previousMap.T === palette[indices[0]]) {
      // Rotate indices by 1..6 to guarantee a visibly different assignment
      const shift = 1 + (Math.floor(rng() * 5));
      const rotated = indices.map((_, idx) => indices[(idx + shift) % 7]);
      for (let i = 0; i < 7; i++) indices[i] = rotated[i];
    }
  }

  const map = {};
  LEVEL_1_ORDER.forEach((type, idx) => {
    map[type] = palette[indices[idx]];
  });
  return map;
}

/**
 * Creates a fresh active piece state at the Guideline spawn position.
 * Board is 10 columns wide (0..9) and 22 rows tall (0..1 hidden, 2..21 visible).
 */
function createPiece(type, colorMap = null) {
  const matrix = SHAPES[type][0];
  const width = matrix[0].length;
  const x = Math.floor((10 - width) / 2);
  // Spawn at row 0 (top hidden buffer row so rows 0..1 hold the piece and it drops into row 2)
  const y = 0;
  return {
    type,
    rotation: 0,
    x,
    y,
    color: colorMap ? colorMap[type] : THEME_PALETTES.neon[0],
  };
}

// ===== src/board.js =====
// src/board.js
// Pure 10x22 Tetris board representation (20 visible rows + 2 hidden spawn rows),
// collision detection, SRS rotation with wall kicks, 3-corner T-Spin detection, and line clearing.


const BOARD_WIDTH = 10;
const VISIBLE_ROWS = 20;
const HIDDEN_ROWS = 2;
const TOTAL_ROWS = VISIBLE_ROWS + HIDDEN_ROWS; // 22

class Board {
  constructor(width = BOARD_WIDTH, height = TOTAL_ROWS) {
    this.width = width;
    this.height = height;
    this.grid = this._createEmptyGrid();
  }

  _createEmptyGrid() {
    return Array.from({ length: this.height }, () => Array(this.width).fill(null));
  }

  reset() {
    this.grid = this._createEmptyGrid();
  }

  /**
   * Checks whether `piece` at `(piece.x + dx, piece.y + dy)` with `rotation`
   * fits without colliding with walls, floor, or existing locked cells.
   */
  isValidPosition(piece, dx = 0, dy = 0, rotation = piece.rotation) {
    const matrix = SHAPES[piece.type][rotation];
    const targetX = piece.x + dx;
    const targetY = piece.y + dy;

    for (let r = 0; r < matrix.length; r++) {
      const row = matrix[r];
      for (let c = 0; c < row.length; c++) {
        if (!row[c]) continue;
        const x = targetX + c;
        const y = targetY + r;

        if (x < 0 || x >= this.width || y >= this.height) {
          return false;
        }
        // Allow cells temporarily at y < 0 during high kicks, otherwise check grid occupancy
        if (y >= 0 && this.grid[y][x] !== null) {
          return false;
        }
      }
    }
    return true;
  }

  /**
   * Attempts to rotate `piece` using SRS wall-kick tables.
   * @param {object} piece - Current piece { type, rotation, x, y, color }
   * @param {number} dir - 1 for CW, -1 for CCW, 2 for 180°
   * @returns {{ success: boolean, x?: number, y?: number, rotation?: number, kickIndex?: number, kickOffset?: [number, number] }}
   */
  tryRotate(piece, dir) {
    const fromRot = piece.rotation;
    const toRot = ((fromRot + dir) % 4 + 4) % 4;
    const kicks = getKickOffsets(piece.type, fromRot, toRot);

    for (let i = 0; i < kicks.length; i++) {
      const [dx, dy] = kicks[i];
      if (this.isValidPosition(piece, dx, dy, toRot)) {
        return {
          success: true,
          x: piece.x + dx,
          y: piece.y + dy,
          rotation: toRot,
          kickIndex: i,
          kickOffset: [dx, dy],
        };
      }
    }

    return { success: false };
  }

  /**
   * Computes the Y position of the ghost piece (hard-drop landing row).
   */
  getGhostY(piece) {
    let dy = 0;
    while (this.isValidPosition(piece, 0, dy + 1, piece.rotation)) {
      dy++;
    }
    return piece.y + dy;
  }

  /**
   * Locks a piece into the board grid.
   * Returns metadata including locked cell coordinates and Guideline lock-out check.
   */
  lockPiece(piece) {
    const matrix = SHAPES[piece.type][piece.rotation];
    const lockedCells = [];

    for (let r = 0; r < matrix.length; r++) {
      for (let c = 0; c < matrix[r].length; c++) {
        if (!matrix[r][c]) continue;
        const x = piece.x + c;
        const y = piece.y + r;
        if (y >= 0 && y < this.height && x >= 0 && x < this.width) {
          this.grid[y][x] = {
            type: piece.type,
            color: piece.color,
          };
          lockedCells.push({ x, y, type: piece.type, color: piece.color });
        }
      }
    }

    // Guideline Lock Out: game over if the entire piece locked above the visible skyline (y < HIDDEN_ROWS)
    const lockOut = lockedCells.length > 0 && lockedCells.every((cell) => cell.y < HIDDEN_ROWS);

    return { lockedCells, lockOut };
  }

  /**
   * Detects T-Spin according to the Guideline 3-Corner Rule.
   * Must be called BEFORE clearing lines while the T piece (or surrounding blocks) are in place.
   * @param {object} piece - The T piece at its final locked position
   * @param {boolean} lastActionWasRotation - Whether the last successful action was a rotation
   * @param {number} lastKickIndex - Index of the SRS kick used (0..4); index 4 upgrades Mini to Full
   * @returns {'none' | 'mini' | 'full'}
   */
  detectTSpin(piece, lastActionWasRotation, lastKickIndex = 0) {
    if (!piece || piece.type !== 'T' || !lastActionWasRotation) {
      return 'none';
    }

    const cx = piece.x + 1;
    const cy = piece.y + 1;

    // 4 corners in clockwise order starting from Top-Left: TL, TR, BR, BL
    const corners = [
      [cx - 1, cy - 1], // 0: TL
      [cx + 1, cy - 1], // 1: TR
      [cx + 1, cy + 1], // 2: BR
      [cx - 1, cy + 1], // 3: BL
    ];

    const isOccupied = ([x, y]) => {
      if (x < 0 || x >= this.width || y >= this.height) return true; // wall/floor counts as occupied
      if (y < 0) return false;
      return this.grid[y][x] !== null;
    };

    const occupiedFlags = corners.map(isOccupied);
    const occupiedCount = occupiedFlags.filter(Boolean).length;

    if (occupiedCount < 3) {
      return 'none';
    }

    // Front corners by rotation:
    // 0 (North): TL(0), TR(1)
    // 1 (East):  TR(1), BR(2)
    // 2 (South): BR(2), BL(3)
    // 3 (West):  BL(3), TL(0)
    const frontCornerA = occupiedFlags[piece.rotation];
    const frontCornerB = occupiedFlags[(piece.rotation + 1) % 4];

    // Guideline rule: Full T-Spin if both front corners are filled OR the 5th kick (index 4, TST kick) was used
    if ((frontCornerA && frontCornerB) || lastKickIndex === 4) {
      return 'full';
    }

    return 'mini';
  }

  /**
   * Finds and removes completed horizontal lines.
   * Returns cleared row indices, destroyed cell details (for colorful particle explosions),
   * and whether the board is now completely empty (Perfect Clear).
   */
  clearLines() {
    const clearedRows = [];
    const destroyedCells = [];
    const remainingGrid = [];

    for (let y = 0; y < this.height; y++) {
      const row = this.grid[y];
      const isFull = row.every((cell) => cell !== null);
      if (isFull) {
        clearedRows.push(y);
        for (let x = 0; x < this.width; x++) {
          destroyedCells.push({
            x,
            y,
            type: row[x].type,
            color: row[x].color,
          });
        }
      } else {
        remainingGrid.push(row);
      }
    }

    if (clearedRows.length > 0) {
      while (remainingGrid.length < this.height) {
        remainingGrid.unshift(Array(this.width).fill(null));
      }
      this.grid = remainingGrid;
    }

    const isPerfectClear =
      clearedRows.length > 0 &&
      this.grid.every((row) => row.every((cell) => cell === null));

    return {
      linesCleared: clearedRows.length,
      clearedRows,
      destroyedCells,
      isPerfectClear,
    };
  }

  isEmpty() {
    return this.grid.every((row) => row.every((cell) => cell === null));
  }

  /**
   * Recolors existing locked cells when the theme or level color map changes (optional or for theme switch).
   */
  applyColorMap(colorMap) {
    if (!colorMap) return;
    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        const cell = this.grid[y][x];
        if (cell && colorMap[cell.type]) {
          cell.color = colorMap[cell.type];
        }
      }
    }
  }

  serialize() {
    return this.grid.map((row) => row.map((cell) => (cell ? { ...cell } : null)));
  }

  restore(serializedGrid) {
    if (!Array.isArray(serializedGrid) || serializedGrid.length !== this.height) return;
    this.grid = serializedGrid.map((row) =>
      row.map((cell) => (cell ? { type: cell.type, color: cell.color } : null))
    );
  }
}

// ===== src/scoring.js =====
// src/scoring.js
// Guideline gravity formula, speed telemetry, and scoring engine
// (Single/Double/Triple/Tetris, T-Spin Full & Mini, Back-to-Back x1.5, Combo, Perfect Clear, Drop points).

/**
 * Guideline gravity formula: seconds per row at a given `level` (1-indexed).
 * Formula: (0.8 - ((level - 1) * 0.007)) ^ (level - 1)
 */
function getGravitySecondsPerRow(level = 1) {
  const clampedLevel = Math.max(1, Math.min(30, level));
  const base = Math.max(0.001, 0.8 - (clampedLevel - 1) * 0.007);
  return Math.pow(base, clampedLevel - 1);
}

/**
 * Returns gravity interval in milliseconds per row.
 */
function getGravityMs(level = 1) {
  return getGravitySecondsPerRow(level) * 1000;
}

/**
 * Returns formatted speed telemetry for the HUD ("oyunun hızı, level hakkında bilgiler").
 * Includes speed multiplier relative to Level 1, rows per second, and G value.
 */
function getSpeedInfo(level = 1, mode = 'marathon') {
  if (mode === 'zen') {
    return {
      level,
      secondsPerRow: Infinity,
      rowsPerSecond: 0,
      multiplier: 'ZEN (0.0x)',
      gValue: '0.00G',
      label: 'Rahat / Yerçekimsiz',
    };
  }
  const sec = getGravitySecondsPerRow(level);
  const rowsPerSec = 1 / sec;
  const mult = 1 / sec; // Level 1 = 1.00x (1 row/sec)
  const gVal = rowsPerSec / 60; // cells per 60Hz frame
  return {
    level,
    secondsPerRow: sec,
    rowsPerSecond: Number(rowsPerSec.toFixed(2)),
    multiplier: `${mult < 10 ? mult.toFixed(2) : Math.round(mult)}x`,
    gValue: `${gVal < 1 ? gVal.toFixed(2) : Math.min(20, gVal).toFixed(1)}G`,
    label: `${rowsPerSec.toFixed(1)} satır/sn`,
  };
}

/**
 * Evaluates a piece lock & line clear action according to the modern Tetris Guideline.
 *
 * @param {object} params
 * @param {number} params.linesCleared - 0..4
 * @param {'none'|'mini'|'full'} params.tSpin - T-Spin detection result
 * @param {number} params.level - Current level (>= 1)
 * @param {number} params.combo - Current combo counter (-1 before first clear, 0 on first clear, 1 on second...)
 * @param {boolean} params.b2bActive - Whether previous line-clearing action was a difficult clear (Tetris or T-Spin line clear)
 * @param {boolean} params.isPerfectClear - Whether the board is completely empty after the clear
 * @returns {{
 *   points: number,
 *   combo: number,
 *   b2bActive: boolean,
 *   b2bTriggered: boolean,
 *   isDifficult: boolean,
 *   callouts: string[],
 *   actionName: string
 * }}
 */
function evaluateTurnScore({
  linesCleared = 0,
  tSpin = 'none',
  level = 1,
  combo = -1,
  b2bActive = false,
  isPerfectClear = false,
}) {
  let basePoints = 0;
  let isDifficult = false;
  let actionName = '';
  const callouts = [];

  if (tSpin === 'full') {
    if (linesCleared === 0) {
      basePoints = 400;
      actionName = 'T-SPIN';
      callouts.push('T-SPIN');
    } else if (linesCleared === 1) {
      basePoints = 800;
      isDifficult = true;
      actionName = 'T-SPIN SINGLE';
      callouts.push('T-SPIN SINGLE');
    } else if (linesCleared === 2) {
      basePoints = 1200;
      isDifficult = true;
      actionName = 'T-SPIN DOUBLE';
      callouts.push('T-SPIN DOUBLE');
    } else if (linesCleared >= 3) {
      basePoints = 1600;
      isDifficult = true;
      actionName = 'T-SPIN TRIPLE';
      callouts.push('T-SPIN TRIPLE');
    }
  } else if (tSpin === 'mini') {
    if (linesCleared === 0) {
      basePoints = 100;
      actionName = 'T-SPIN MINI';
      callouts.push('T-SPIN MINI');
    } else if (linesCleared === 1) {
      basePoints = 200;
      isDifficult = true;
      actionName = 'T-SPIN MINI SINGLE';
      callouts.push('T-SPIN MINI');
    } else if (linesCleared >= 2) {
      basePoints = 400;
      isDifficult = true;
      actionName = 'T-SPIN MINI DOUBLE';
      callouts.push('T-SPIN MINI DOUBLE');
    }
  } else {
    // Standard line clears
    if (linesCleared === 1) {
      basePoints = 100;
      actionName = 'SINGLE';
    } else if (linesCleared === 2) {
      basePoints = 300;
      actionName = 'DOUBLE';
      callouts.push('DOUBLE');
    } else if (linesCleared === 3) {
      basePoints = 500;
      actionName = 'TRIPLE';
      callouts.push('TRIPLE');
    } else if (linesCleared >= 4) {
      basePoints = 800;
      isDifficult = true;
      actionName = 'TETRIS';
      callouts.push('TETRIS');
    }
  }

  let b2bTriggered = false;
  let nextB2B = b2bActive;

  if (linesCleared > 0) {
    if (isDifficult) {
      if (b2bActive) {
        basePoints = Math.floor(basePoints * 1.5);
        b2bTriggered = true;
        callouts.push('B2B');
      }
      nextB2B = true;
    } else {
      // Non-difficult line clear (Single/Double/Triple without T-Spin) breaks B2B
      nextB2B = false;
    }
  }

  let totalPoints = basePoints * level;

  // Combo update & bonus
  let nextCombo = combo;
  if (linesCleared > 0) {
    nextCombo = combo + 1;
    if (nextCombo >= 1) {
      totalPoints += 50 * nextCombo * level;
      callouts.push(`COMBO x${nextCombo}`);
    }
  } else {
    nextCombo = -1;
  }

  // Perfect Clear bonus
  if (isPerfectClear && linesCleared > 0) {
    const pcTable = [0, 800, 1200, 1800, b2bTriggered ? 3200 : 2000];
    const pcBonus = (pcTable[Math.min(4, linesCleared)] || 2000) * level;
    totalPoints += pcBonus;
    callouts.push('PERFECT CLEAR');
  }

  return {
    points: totalPoints,
    combo: nextCombo,
    b2bActive: nextB2B,
    b2bTriggered,
    isDifficult,
    callouts,
    actionName,
  };
}

/**
 * Calculates drop points:
 * - Soft drop: 1 point per cell
 * - Hard drop: 2 points per cell
 */
function calculateDropScore(cellsDropped, type = 'soft') {
  if (cellsDropped <= 0) return 0;
  return type === 'hard' ? cellsDropped * 2 : cellsDropped * 1;
}

// ===== src/game.js =====
// src/game.js
// Pure, frame-rate independent Tetris game state machine.
// Completely decoupled from DOM, Canvas, and Web Audio so it can be unit-tested in Node.


const GAME_STATES = Object.freeze({
  IDLE: 'IDLE',
  PLAYING: 'PLAYING',
  PAUSED: 'PAUSED',
  COUNTDOWN: 'COUNTDOWN',
  GAME_OVER: 'GAME_OVER',
  VICTORY: 'VICTORY',
});

const LOCK_DELAY_MS = 500;
const MAX_LOCK_RESETS = 15;
const SPRINT_TARGET_LINES = 40;
const ULTRA_DURATION_MS = 120_000; // 2 minutes

class TetrisGame {
  constructor(options = {}) {
    this.seed = options.seed ?? Date.now();
    this.onEvent = options.onEvent || (() => {});

    this.settings = {
      theme: 'neon',
      colorblind: false,
      randomLevelColors: true,
      ghost: true,
      allow180: true,
      infinityLock: false,
      sdf: 20, // Soft drop factor multiplier
      ...options.settings,
    };

    this.board = new Board();
    this.randomizer = new BagRandomizer(this.seed);
    this.mode = 'marathon';
    this.state = GAME_STATES.IDLE;

    this._initSessionState();
  }

  _initSessionState() {
    this.score = 0;
    this.lines = 0;
    this.level = 1;
    this.combo = -1;
    this.b2bActive = false;
    this.elapsedMs = 0;

    // Detailed telemetry & stats
    this.stats = {
      piecesPlaced: 0,
      tetrisCount: 0,
      tSpinCount: 0,
      maxCombo: 0,
      perfectClears: 0,
      singleCount: 0,
      doubleCount: 0,
      tripleCount: 0,
    };

    this.colorMap = generateLevelColorMap({
      level: 1,
      theme: this.settings.theme,
      colorblind: this.settings.colorblind,
      randomLevelColors: this.settings.randomLevelColors,
      seed: this.seed,
    });

    this.activePiece = null;
    this.holdPieceType = null;
    this.canHold = true;

    // Gravity & lock delay timers
    this.gravityAccumulatorMs = 0;
    this.lockTimerMs = 0;
    this.lockResetCount = 0;
    this.lowestY = 0;

    // T-spin tracking for current piece
    this.lastActionWasRotation = false;
    this.lastKickIndex = 0;
  }

  /**
   * Starts a new game in the specified mode ('marathon' | 'sprint' | 'ultra' | 'zen').
   */
  start(mode = 'marathon', seed = Date.now()) {
    this.mode = mode;
    this.seed = seed;
    this.board.reset();
    this.randomizer.reset(seed);
    this._initSessionState();
    this.state = GAME_STATES.PLAYING;
    this._spawnNextPiece();
    this._emit('gameStart', {
      mode: this.mode,
      level: this.level,
      colorMap: { ...this.colorMap },
      speedInfo: this.getSpeedTelemetry(),
    });
  }

  updateSettings(partialSettings = {}) {
    const prevTheme = this.settings.theme;
    const prevCB = this.settings.colorblind;
    const prevRandom = this.settings.randomLevelColors;

    this.settings = { ...this.settings, ...partialSettings };

    if (
      prevTheme !== this.settings.theme ||
      prevCB !== this.settings.colorblind ||
      prevRandom !== this.settings.randomLevelColors
    ) {
      this.colorMap = generateLevelColorMap({
        level: this.level,
        theme: this.settings.theme,
        colorblind: this.settings.colorblind,
        randomLevelColors: this.settings.randomLevelColors,
        seed: this.seed,
      });
      if (this.activePiece) {
        this.activePiece.color = this.colorMap[this.activePiece.type];
      }
      this.board.applyColorMap(this.colorMap);
      this._emit('paletteChanged', { colorMap: { ...this.colorMap }, level: this.level });
    }
  }

  pause() {
    if (this.state === GAME_STATES.PLAYING) {
      this.state = GAME_STATES.PAUSED;
      this._emit('pause', {});
    }
  }

  resume() {
    if (this.state === GAME_STATES.PAUSED || this.state === GAME_STATES.COUNTDOWN) {
      this.state = GAME_STATES.PLAYING;
      this._emit('resume', {});
    }
  }

  /**
   * Advances simulation by `dtMs` milliseconds.
   */
  update(dtMs, isSoftDropping = false) {
    if (this.state !== GAME_STATES.PLAYING || !this.activePiece) return;

    this.elapsedMs += dtMs;

    // Check Ultra mode time limit (2 minutes)
    if (this.mode === 'ultra' && this.elapsedMs >= ULTRA_DURATION_MS) {
      this.elapsedMs = ULTRA_DURATION_MS;
      this.state = GAME_STATES.VICTORY;
      this._emit('gameOver', {
        reason: 'timeUp',
        victory: true,
        stats: this.getSummaryStats(),
      });
      return;
    }

    // Gravity calculation
    const baseGravityMs = this.mode === 'zen' ? Infinity : getGravityMs(this.level);
    const sdf = Math.max(1, Number(this.settings.sdf) || 20);
    const effectiveGravityMs = isSoftDropping
      ? Math.min(baseGravityMs, Math.max(8, (this.mode === 'zen' ? 500 : baseGravityMs) / sdf))
      : baseGravityMs;

    if (Number.isFinite(effectiveGravityMs)) {
      this.gravityAccumulatorMs += dtMs;
      while (this.gravityAccumulatorMs >= effectiveGravityMs) {
        this.gravityAccumulatorMs -= effectiveGravityMs;
        if (this._canMoveDown()) {
          this.activePiece.y += 1;
          this.lastActionWasRotation = false;
          if (isSoftDropping) {
            const pts = calculateDropScore(1, 'soft');
            this.score += pts;
            this._emit('softDropStep', { points: pts });
          }
          this._updateLowestY();
        } else {
          this.gravityAccumulatorMs = 0;
          break;
        }
      }
    }

    // Lock delay processing when resting on a surface
    if (!this._canMoveDown()) {
      this.lockTimerMs += dtMs;
      if (this.lockTimerMs >= LOCK_DELAY_MS) {
        this._lockActivePiece();
      }
    } else {
      this.lockTimerMs = 0;
    }
  }

  _canMoveDown() {
    if (!this.activePiece) return false;
    return this.board.isValidPosition(this.activePiece, 0, 1, this.activePiece.rotation);
  }

  _updateLowestY() {
    if (!this.activePiece) return;
    if (this.activePiece.y > this.lowestY) {
      this.lowestY = this.activePiece.y;
      this.lockResetCount = 0;
      this.lockTimerMs = 0;
    }
  }

  /**
   * Resets lock timer on valid move/rotation if allowed by the 15-reset rule (or infinity setting).
   */
  _registerMoveOrRotateReset() {
    const maxResets = this.settings.infinityLock ? Infinity : MAX_LOCK_RESETS;
    if (this.lockResetCount < maxResets) {
      this.lockTimerMs = 0;
      if (!this._canMoveDown()) {
        this.lockResetCount += 1;
      }
    }
  }

  moveLeft() {
    if (this.state !== GAME_STATES.PLAYING || !this.activePiece) return false;
    if (this.board.isValidPosition(this.activePiece, -1, 0)) {
      this.activePiece.x -= 1;
      this.lastActionWasRotation = false;
      this._registerMoveOrRotateReset();
      this._emit('move', { dir: -1, x: this.activePiece.x, y: this.activePiece.y });
      return true;
    }
    return false;
  }

  moveRight() {
    if (this.state !== GAME_STATES.PLAYING || !this.activePiece) return false;
    if (this.board.isValidPosition(this.activePiece, 1, 0)) {
      this.activePiece.x += 1;
      this.lastActionWasRotation = false;
      this._registerMoveOrRotateReset();
      this._emit('move', { dir: 1, x: this.activePiece.x, y: this.activePiece.y });
      return true;
    }
    return false;
  }

  softDropStep() {
    if (this.state !== GAME_STATES.PLAYING || !this.activePiece) return false;
    if (this._canMoveDown()) {
      this.activePiece.y += 1;
      this.lastActionWasRotation = false;
      const pts = calculateDropScore(1, 'soft');
      this.score += pts;
      this._updateLowestY();
      this._emit('softDropStep', { points: pts, y: this.activePiece.y });
      return true;
    }
    return false;
  }

  hardDrop() {
    if (this.state !== GAME_STATES.PLAYING || !this.activePiece) return 0;
    const startY = this.activePiece.y;
    const targetY = this.board.getGhostY(this.activePiece);
    const cellsDropped = Math.max(0, targetY - startY);

    if (cellsDropped > 0) {
      this.activePiece.y = targetY;
      this.lastActionWasRotation = false;
      this.score += calculateDropScore(cellsDropped, 'hard');
    }

    this._emit('hardDrop', {
      piece: { ...this.activePiece },
      startY,
      endY: targetY,
      cellsDropped,
    });

    this._lockActivePiece();
    return cellsDropped;
  }

  /**
   * Rotate active piece: dir = 1 (CW), -1 (CCW), 2 (180°).
   */
  rotate(dir = 1) {
    if (this.state !== GAME_STATES.PLAYING || !this.activePiece) return false;
    if (dir === 2 && !this.settings.allow180) return false;

    const result = this.board.tryRotate(this.activePiece, dir);
    if (result.success) {
      this.activePiece.x = result.x;
      this.activePiece.y = result.y;
      this.activePiece.rotation = result.rotation;
      this.lastActionWasRotation = true;
      this.lastKickIndex = result.kickIndex;
      this._updateLowestY();
      this._registerMoveOrRotateReset();
      this._emit('rotate', {
        dir,
        rotation: result.rotation,
        kickIndex: result.kickIndex,
        kickOffset: result.kickOffset,
      });
      return true;
    }
    return false;
  }

  /**
   * Swaps the active piece with the Hold slot (max once per drop).
   */
  hold() {
    if (this.state !== GAME_STATES.PLAYING || !this.activePiece || !this.canHold) {
      return false;
    }

    const currentType = this.activePiece.type;
    const previousHold = this.holdPieceType;
    this.holdPieceType = currentType;
    this.canHold = false;

    if (previousHold) {
      this._spawnSpecificPiece(previousHold);
    } else {
      this._spawnNextPiece(false);
    }

    this._emit('hold', { holdPieceType: this.holdPieceType });
    return true;
  }

  _spawnNextPiece(resetHoldFlag = true) {
    const nextType = this.randomizer.next();
    if (resetHoldFlag) {
      this.canHold = true;
    }
    this._spawnSpecificPiece(nextType);
  }

  _spawnSpecificPiece(type) {
    const piece = createPiece(type, this.colorMap);
    this.activePiece = piece;
    this.gravityAccumulatorMs = 0;
    this.lockTimerMs = 0;
    this.lockResetCount = 0;
    this.lowestY = piece.y;
    this.lastActionWasRotation = false;
    this.lastKickIndex = 0;

    // Check Guideline Block Out condition
    if (!this.board.isValidPosition(piece, 0, 0)) {
      if (this.board.isValidPosition(piece, 0, -1)) {
        piece.y -= 1;
      } else if (this.mode === 'zen') {
        this._zenReliefClear();
      } else {
        this.state = GAME_STATES.GAME_OVER;
        this._emit('gameOver', {
          reason: 'blockOut',
          victory: false,
          stats: this.getSummaryStats(),
        });
      }
    }
  }

  _zenReliefClear() {
    // In Zen mode, clear the upper half of the board with colorful particles instead of ending the game
    const destroyedCells = [];
    for (let y = 0; y < 12; y++) {
      for (let x = 0; x < this.board.width; x++) {
        if (this.board.grid[y][x]) {
          destroyedCells.push({
            x,
            y,
            ...this.board.grid[y][x],
          });
          this.board.grid[y][x] = null;
        }
      }
    }
    this._emit('zenClear', { destroyedCells });
  }

  _lockActivePiece() {
    if (!this.activePiece) return;

    const piece = this.activePiece;
    const { lockedCells, lockOut } = this.board.lockPiece(piece);
    this.stats.piecesPlaced += 1;

    // Detect T-Spin BEFORE clearing lines (3-corner rule requires surrounding blocks intact)
    const tSpin = this.board.detectTSpin(piece, this.lastActionWasRotation, this.lastKickIndex);
    if (tSpin !== 'none') {
      this.stats.tSpinCount += 1;
    }

    // Clear full rows
    const { linesCleared, clearedRows, destroyedCells, isPerfectClear } = this.board.clearLines();

    if (linesCleared === 1) this.stats.singleCount += 1;
    else if (linesCleared === 2) this.stats.doubleCount += 1;
    else if (linesCleared === 3) this.stats.tripleCount += 1;
    else if (linesCleared >= 4) this.stats.tetrisCount += 1;

    if (isPerfectClear) {
      this.stats.perfectClears += 1;
    }

    // Evaluate Guideline score
    const scoreResult = evaluateTurnScore({
      linesCleared,
      tSpin,
      level: this.level,
      combo: this.combo,
      b2bActive: this.b2bActive,
      isPerfectClear,
    });

    this.score += scoreResult.points;
    this.combo = scoreResult.combo;
    this.b2bActive = scoreResult.b2bActive;
    if (this.combo > this.stats.maxCombo) {
      this.stats.maxCombo = this.combo;
    }

    const prevLevel = this.level;
    this.lines += linesCleared;

    // Level progression every 10 lines
    const computedLevel = Math.floor(this.lines / 10) + 1;
    const leveledUp = computedLevel > prevLevel;
    if (leveledUp) {
      this.level = computedLevel;
      // Randomize piece colors on every new level as requested ("her yeni bölümde random olarak değişsin")
      this.colorMap = generateLevelColorMap({
        level: this.level,
        theme: this.settings.theme,
        colorblind: this.settings.colorblind,
        randomLevelColors: this.settings.randomLevelColors,
        previousMap: this.colorMap,
        seed: this.seed,
      });
    }

    this._emit('pieceLocked', {
      piece,
      lockedCells,
      linesCleared,
      clearedRows,
      destroyedCells,
      tSpin,
      isPerfectClear,
      scoreAdded: scoreResult.points,
      combo: this.combo,
      b2bTriggered: scoreResult.b2bTriggered,
      callouts: scoreResult.callouts,
      leveledUp,
      level: this.level,
      colorMap: { ...this.colorMap },
    });

    if (leveledUp) {
      this._emit('levelUp', {
        level: this.level,
        colorMap: { ...this.colorMap },
        speedInfo: this.getSpeedTelemetry(),
      });
    }

    // Check Lock Out condition (all cells locked in hidden rows)
    if (lockOut && linesCleared === 0) {
      if (this.mode === 'zen') {
        this._zenReliefClear();
      } else {
        this.state = GAME_STATES.GAME_OVER;
        this._emit('gameOver', {
          reason: 'lockOut',
          victory: false,
          stats: this.getSummaryStats(),
        });
        return;
      }
    }

    // Check Sprint mode victory (40 lines cleared)
    if (this.mode === 'sprint' && this.lines >= SPRINT_TARGET_LINES) {
      this.state = GAME_STATES.VICTORY;
      this._emit('gameOver', {
        reason: 'sprintComplete',
        victory: true,
        stats: this.getSummaryStats(),
      });
      return;
    }

    // Spawn next piece
    this._spawnNextPiece(true);
  }

  getNextQueue(count = 5) {
    return this.randomizer.peek(count);
  }

  getGhostY() {
    if (!this.activePiece) return 0;
    return this.board.getGhostY(this.activePiece);
  }

  getSpeedTelemetry() {
    return getSpeedInfo(this.level, this.mode);
  }

  getSummaryStats() {
    const seconds = Math.max(0.001, this.elapsedMs / 1000);
    const pps = Number((this.stats.piecesPlaced / seconds).toFixed(2));
    return {
      mode: this.mode,
      score: this.score,
      lines: this.lines,
      level: this.level,
      elapsedMs: Math.round(this.elapsedMs),
      pps,
      pieces: this.stats.piecesPlaced,
      tetrisCount: this.stats.tetrisCount,
      tSpinCount: this.stats.tSpinCount,
      maxCombo: Math.max(0, this.stats.maxCombo),
      perfectClears: this.stats.perfectClears,
      speedInfo: this.getSpeedTelemetry(),
    };
  }

  /**
   * Serializes the entire game state so an in-progress game can be saved & restored.
   */
  serialize() {
    return {
      mode: this.mode,
      state: this.state,
      seed: this.seed,
      score: this.score,
      lines: this.lines,
      level: this.level,
      combo: this.combo,
      b2bActive: this.b2bActive,
      elapsedMs: this.elapsedMs,
      stats: { ...this.stats },
      colorMap: { ...this.colorMap },
      activePiece: this.activePiece ? { ...this.activePiece } : null,
      holdPieceType: this.holdPieceType,
      canHold: this.canHold,
      board: this.board.serialize(),
      randomizer: this.randomizer.serialize(),
    };
  }

  restore(snapshot) {
    if (!snapshot || !snapshot.board) return false;
    this.mode = snapshot.mode || 'marathon';
    this.seed = snapshot.seed || Date.now();
    this.score = snapshot.score || 0;
    this.lines = snapshot.lines || 0;
    this.level = snapshot.level || 1;
    this.combo = snapshot.combo ?? -1;
    this.b2bActive = Boolean(snapshot.b2bActive);
    this.elapsedMs = snapshot.elapsedMs || 0;
    this.stats = { ...this.stats, ...(snapshot.stats || {}) };
    this.colorMap = snapshot.colorMap || this.colorMap;
    this.activePiece = snapshot.activePiece ? { ...snapshot.activePiece } : null;
    this.holdPieceType = snapshot.holdPieceType || null;
    this.canHold = snapshot.canHold !== false;
    this.board.restore(snapshot.board);
    this.randomizer.restore(snapshot.randomizer);
    this.state = GAME_STATES.PAUSED;
    return true;
  }

  _emit(type, payload) {
    if (typeof this.onEvent === 'function') {
      this.onEvent(type, payload);
    }
  }
}

// ===== src/effects.js =====
// src/effects.js
// High-performance visual effects system with object-pooled particles (zero GC churn in hot loop),
// colorful per-block explosions on line clears, hard-drop trails, lock squash/flash,
// screen shake, level-up pulse, and floating action callouts.


const MAX_PARTICLES = 400;

class EffectsManager {
  constructor(settings = {}) {
    this.settings = {
      particles: true,
      screenShake: true,
      reducedMotion: false,
      ...settings,
    };

    // Pre-allocated particle pool to avoid per-frame allocations
    this.pool = Array.from({ length: MAX_PARTICLES }, () => ({
      active: false,
      x: 0,
      y: 0,
      vx: 0,
      vy: 0,
      size: 4,
      color: '#ffffff',
      alpha: 1,
      life: 0,
      maxLife: 500,
      rotation: 0,
      vRot: 0,
      shape: 'shard', // 'shard' | 'spark' | 'ring'
    }));
    this.activeCount = 0;
    this.qualityScale = 1.0; // Adaptive quality multiplier (0.35 .. 1.0)

    // Hard-drop vertical light beams
    this.trails = [];

    // Recently locked cell flashes / squash
    this.lockFlashes = [];

    // Row clear flash bars
    this.rowFlashes = [];

    // Floating callout banners ("TETRIS", "T-SPIN DOUBLE", "COMBO x3", etc.)
    this.callouts = [];

    // Screen shake state
    this.shakeTimeMs = 0;
    this.shakeDurationMs = 0;
    this.shakeIntensity = 0;
    this.shakeOffsetX = 0;
    this.shakeOffsetY = 0;

    // Level-up border pulse
    this.levelPulse = 0;
  }

  updateSettings(partial = {}) {
    this.settings = { ...this.settings, ...partial };
  }

  setQualityScale(scale) {
    this.qualityScale = Math.max(0.3, Math.min(1.0, scale));
  }

  _acquireParticle() {
    for (let i = 0; i < MAX_PARTICLES; i++) {
      if (!this.pool[i].active) {
        this.pool[i].active = true;
        return this.pool[i];
      }
    }
    return null;
  }

  /**
   * Spawns colorful particle explosions for each destroyed cell when lines are cleared.
   * Each cell explodes in its own color plus bright core sparks.
   */
  spawnLineExplosion(destroyedCells, cellSize) {
    if (!this.settings.particles || this.settings.reducedMotion) return;

    const countPerCell = Math.max(
      4,
      Math.round((destroyedCells.length >= 30 ? 9 : 12) * this.qualityScale)
    );

    for (let i = 0; i < destroyedCells.length; i++) {
      const cell = destroyedCells[i];
      const visRow = cell.y - HIDDEN_ROWS;
      if (visRow < 0) continue;

      const cx = (cell.x + 0.5) * cellSize;
      const cy = (visRow + 0.5) * cellSize;

      // Expanding shockwave ring per cell
      const ring = this._acquireParticle();
      if (ring) {
        ring.x = cx;
        ring.y = cy;
        ring.vx = 0;
        ring.vy = 0;
        ring.size = cellSize * 0.25;
        ring.color = cell.color;
        ring.alpha = 0.9;
        ring.life = 0;
        ring.maxLife = 360;
        ring.shape = 'ring';
      }

      // Colorful shards & glowing sparks
      for (let p = 0; p < countPerCell; p++) {
        const pt = this._acquireParticle();
        if (!pt) break;

        const angle = Math.random() * Math.PI * 2;
        const speed = (1.5 + Math.random() * 6.5) * (cellSize / 28);
        pt.x = cx + (Math.random() - 0.5) * cellSize * 0.6;
        pt.y = cy + (Math.random() - 0.5) * cellSize * 0.6;
        pt.vx = Math.cos(angle) * speed;
        pt.vy = Math.sin(angle) * speed - (1.2 + Math.random() * 2.0);
        pt.size = (2.5 + Math.random() * 5.5) * (cellSize / 28);
        // Mix cell's primary color with occasional white-hot spark
        pt.color = p % 5 === 0 ? '#ffffff' : cell.color;
        pt.alpha = 1;
        pt.life = 0;
        pt.maxLife = 420 + Math.random() * 420;
        pt.rotation = Math.random() * Math.PI * 2;
        pt.vRot = (Math.random() - 0.5) * 0.22;
        pt.shape = p % 3 === 0 ? 'spark' : 'shard';
      }
    }
  }

  /**
   * Spawns horizontal flash bars across cleared rows.
   */
  spawnRowFlashes(clearedRows) {
    for (let i = 0; i < clearedRows.length; i++) {
      const visRow = clearedRows[i] - HIDDEN_ROWS;
      if (visRow >= 0) {
        this.rowFlashes.push({
          row: visRow,
          life: 0,
          maxLife: 240,
        });
      }
    }
  }

  /**
   * Spawns a vertical light trail when a piece hard drops.
   */
  spawnHardDropTrail(piece, startY, endY, cellSize) {
    if (this.settings.reducedMotion || endY <= startY) return;
    const matrix = SHAPES[piece.type][piece.rotation];
    let minCol = 4;
    let maxCol = 0;
    for (let r = 0; r < matrix.length; r++) {
      for (let c = 0; c < matrix[r].length; c++) {
        if (matrix[r][c]) {
          if (c < minCol) minCol = c;
          if (c > maxCol) maxCol = c;
        }
      }
    }

    this.trails.push({
      x: piece.x + minCol,
      widthCols: maxCol - minCol + 1,
      startY: Math.max(0, startY - HIDDEN_ROWS),
      endY: Math.max(0, endY - HIDDEN_ROWS + 1),
      color: piece.color,
      life: 0,
      maxLife: 200,
    });

    // Small dust sparks on hard drop impact
    if (this.settings.particles) {
      const impactX = (piece.x + (minCol + maxCol + 1) * 0.5) * cellSize;
      const impactY = Math.max(0, endY - HIDDEN_ROWS + 1.5) * cellSize;
      for (let i = 0; i < 6; i++) {
        const pt = this._acquireParticle();
        if (!pt) break;
        pt.x = impactX + (Math.random() - 0.5) * cellSize * 1.5;
        pt.y = impactY;
        pt.vx = (Math.random() - 0.5) * 3.5;
        pt.vy = -(0.8 + Math.random() * 2.5);
        pt.size = 3;
        pt.color = piece.color;
        pt.alpha = 0.85;
        pt.life = 0;
        pt.maxLife = 260;
        pt.rotation = 0;
        pt.vRot = 0.1;
        pt.shape = 'spark';
      }
    }
  }

  /**
   * Spawns a brief squash/glow animation on newly locked cells.
   */
  spawnLockFlash(lockedCells) {
    for (let i = 0; i < lockedCells.length; i++) {
      const cell = lockedCells[i];
      const visRow = cell.y - HIDDEN_ROWS;
      if (visRow >= 0) {
        this.lockFlashes.push({
          x: cell.x,
          y: visRow,
          color: cell.color,
          life: 0,
          maxLife: 180,
        });
      }
    }
  }

  /**
   * Triggers camera shake (respects screenShake and reducedMotion settings).
   */
  triggerShake(intensity = 6, durationMs = 200) {
    if (!this.settings.screenShake || this.settings.reducedMotion) return;
    this.shakeIntensity = Math.max(this.shakeIntensity, intensity);
    this.shakeDurationMs = Math.max(this.shakeDurationMs, durationMs);
    this.shakeTimeMs = 0;
  }

  triggerLevelUpPulse() {
    if (this.settings.reducedMotion) return;
    this.levelPulse = 1.0;
  }

  /**
   * Adds a floating text callout on the playfield ("TETRIS", "T-SPIN DOUBLE", "B2B", etc.).
   */
  addCallout(text, color = '#00e5ff') {
    const verticalOffset = this.callouts.length * 28;
    this.callouts.push({
      text,
      color,
      offsetY: verticalOffset,
      life: 0,
      maxLife: 1150,
    });
  }

  update(dtMs) {
    // Update screen shake
    if (this.shakeTimeMs < this.shakeDurationMs) {
      this.shakeTimeMs += dtMs;
      const progress = 1 - Math.min(1, this.shakeTimeMs / this.shakeDurationMs);
      const mag = this.shakeIntensity * progress;
      this.shakeOffsetX = (Math.random() * 2 - 1) * mag;
      this.shakeOffsetY = (Math.random() * 2 - 1) * mag;
    } else {
      this.shakeOffsetX = 0;
      this.shakeOffsetY = 0;
      this.shakeIntensity = 0;
      this.shakeDurationMs = 0;
    }

    // Update level pulse
    if (this.levelPulse > 0) {
      this.levelPulse = Math.max(0, this.levelPulse - dtMs / 900);
    }

    // Update particles
    const dtFactor = dtMs / 16.667;
    let active = 0;
    for (let i = 0; i < MAX_PARTICLES; i++) {
      const p = this.pool[i];
      if (!p.active) continue;
      p.life += dtMs;
      if (p.life >= p.maxLife) {
        p.active = false;
        continue;
      }
      active++;
      const t = p.life / p.maxLife;
      p.alpha = 1 - t * t;
      if (p.shape === 'ring') {
        p.size += 1.8 * dtFactor;
      } else {
        p.x += p.vx * dtFactor;
        p.y += p.vy * dtFactor;
        p.vy += 0.22 * dtFactor; // gravity
        p.vx *= 0.985;
        p.rotation += p.vRot * dtFactor;
      }
    }
    this.activeCount = active;

    // Update trails
    for (let i = this.trails.length - 1; i >= 0; i--) {
      this.trails[i].life += dtMs;
      if (this.trails[i].life >= this.trails[i].maxLife) {
        this.trails.splice(i, 1);
      }
    }

    // Update lock flashes
    for (let i = this.lockFlashes.length - 1; i >= 0; i--) {
      this.lockFlashes[i].life += dtMs;
      if (this.lockFlashes[i].life >= this.lockFlashes[i].maxLife) {
        this.lockFlashes.splice(i, 1);
      }
    }

    // Update row flashes
    for (let i = this.rowFlashes.length - 1; i >= 0; i--) {
      this.rowFlashes[i].life += dtMs;
      if (this.rowFlashes[i].life >= this.rowFlashes[i].maxLife) {
        this.rowFlashes.splice(i, 1);
      }
    }

    // Update floating callouts
    for (let i = this.callouts.length - 1; i >= 0; i--) {
      this.callouts[i].life += dtMs;
      if (this.callouts[i].life >= this.callouts[i].maxLife) {
        this.callouts.splice(i, 1);
      }
    }
  }

  /**
   * Renders background trails & row flashes before or after board blocks.
   */
  renderUnderlay(ctx, cellSize, boardWidthPx) {
    // Hard drop light trails
    for (let i = 0; i < this.trails.length; i++) {
      const tr = this.trails[i];
      const alpha = (1 - tr.life / tr.maxLife) * 0.38;
      const x = tr.x * cellSize;
      const y = tr.startY * cellSize;
      const w = tr.widthCols * cellSize;
      const h = Math.max(cellSize, (tr.endY - tr.startY) * cellSize);

      const grad = ctx.createLinearGradient(0, y, 0, y + h);
      grad.addColorStop(0, 'rgba(255,255,255,0)');
      grad.addColorStop(1, tr.color);
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.fillStyle = grad;
      ctx.fillRect(x, y, w, h);
      ctx.restore();
    }

    // Row clear flash bars
    for (let i = 0; i < this.rowFlashes.length; i++) {
      const rf = this.rowFlashes[i];
      const t = rf.life / rf.maxLife;
      const alpha = (1 - t) * 0.85;
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, rf.row * cellSize, boardWidthPx, cellSize);
      ctx.restore();
    }
  }

  /**
   * Renders lock flashes, particles, level-up pulse, and floating callout text on top of the board.
   */
  renderOverlay(ctx, cellSize, boardWidthPx, boardHeightPx) {
    // Lock cell squash/flash
    for (let i = 0; i < this.lockFlashes.length; i++) {
      const lf = this.lockFlashes[i];
      const t = lf.life / lf.maxLife;
      const alpha = (1 - t) * 0.65;
      const squash = Math.sin(t * Math.PI) * 2.5;
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(
        lf.x * cellSize - squash * 0.5,
        lf.y * cellSize + squash * 0.5,
        cellSize + squash,
        cellSize - squash
      );
      ctx.restore();
    }

    // Level-up golden/cyan border pulse
    if (this.levelPulse > 0) {
      ctx.save();
      ctx.strokeStyle = `rgba(0, 229, 255, ${this.levelPulse * 0.85})`;
      ctx.lineWidth = 4 + this.levelPulse * 6;
      ctx.strokeRect(2, 2, boardWidthPx - 4, boardHeightPx - 4);
      ctx.restore();
    }

    // Particle pool
    for (let i = 0; i < MAX_PARTICLES; i++) {
      const p = this.pool[i];
      if (!p.active) continue;

      ctx.save();
      ctx.globalAlpha = Math.max(0, p.alpha);

      if (p.shape === 'ring') {
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 2.2;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.stroke();
      } else if (p.shape === 'spark') {
        ctx.fillStyle = p.color;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 8;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * 0.65, 0, Math.PI * 2);
        ctx.fill();
      } else {
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rotation);
        ctx.fillStyle = p.color;
        const s = p.size;
        ctx.fillRect(-s * 0.5, -s * 0.5, s, s);
        ctx.fillStyle = 'rgba(255,255,255,0.45)';
        ctx.fillRect(-s * 0.3, -s * 0.3, s * 0.35, s * 0.35);
      }

      ctx.restore();
    }

    // Floating callouts ("TETRIS", "T-SPIN DOUBLE", "B2B", "COMBO x3", etc.)
    for (let i = 0; i < this.callouts.length; i++) {
      const c = this.callouts[i];
      const t = c.life / c.maxLife;
      const alpha = t < 0.15 ? t / 0.15 : 1 - Math.pow((t - 0.15) / 0.85, 2);
      const y = boardHeightPx * 0.36 - t * 48 + c.offsetY;
      const scale = t < 0.12 ? 0.75 + (t / 0.12) * 0.35 : 1.0;

      ctx.save();
      ctx.globalAlpha = Math.max(0, alpha);
      ctx.translate(boardWidthPx * 0.5, y);
      ctx.scale(scale, scale);
      ctx.font = `900 ${Math.max(15, Math.round(cellSize * 0.72))}px system-ui, -apple-system, sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.lineWidth = 4;
      ctx.strokeStyle = 'rgba(8, 10, 22, 0.92)';
      ctx.strokeText(c.text, 0, 0);
      ctx.fillStyle = c.color;
      ctx.fillText(c.text, 0, 0);
      ctx.restore();
    }
  }

  clear() {
    for (let i = 0; i < MAX_PARTICLES; i++) {
      this.pool[i].active = false;
    }
    this.trails.length = 0;
    this.lockFlashes.length = 0;
    this.rowFlashes.length = 0;
    this.callouts.length = 0;
    this.shakeTimeMs = 0;
    this.shakeDurationMs = 0;
    this.shakeOffsetX = 0;
    this.shakeOffsetY = 0;
  }
}

// ===== src/renderer.js =====
// src/renderer.js
// HiDPI-aware 2D Canvas renderer with offscreen block sprite caching,
// animated starfield background, ghost piece, lock-delay visual cue,
// Next-5 queue, Hold slot, and game-over cascade animation.


class Renderer {
  constructor({ boardCanvas, holdCanvas, nextCanvas, bgCanvas, effects, settings = {} }) {
    this.boardCanvas = boardCanvas;
    this.boardCtx = boardCanvas.getContext('2d', { alpha: false });

    this.holdCanvas = holdCanvas;
    this.holdCtx = holdCanvas ? holdCanvas.getContext('2d') : null;

    this.nextCanvas = nextCanvas;
    this.nextCtx = nextCanvas ? nextCanvas.getContext('2d') : null;

    this.bgCanvas = bgCanvas;
    this.bgCtx = bgCanvas ? bgCanvas.getContext('2d') : null;

    this.effects = effects;
    this.settings = {
      theme: 'neon',
      grid: true,
      ghost: true,
      colorblind: false,
      reducedMotion: false,
      ...settings,
    };

    this.dpr = Math.min(window.devicePixelRatio || 1, 3);
    this.cellSize = 28;
    this.boardWidthPx = BOARD_WIDTH * this.cellSize;
    this.boardHeightPx = VISIBLE_ROWS * this.cellSize;

    // Offscreen sprite cache: key = `${color}_${size}_${theme}`
    this.spriteCache = new Map();

    // Animated starfield particles for background canvas
    this.stars = Array.from({ length: 55 }, () => ({
      x: Math.random(),
      y: Math.random(),
      size: 0.8 + Math.random() * 1.8,
      speed: 0.008 + Math.random() * 0.025,
      phase: Math.random() * Math.PI * 2,
    }));

    // Game-over collapse progress (0 .. 1)
    this.gameOverAnim = 0;
  }

  updateSettings(partial = {}) {
    const themeChanged = partial.theme && partial.theme !== this.settings.theme;
    this.settings = { ...this.settings, ...partial };
    if (themeChanged) {
      this.spriteCache.clear();
    }
  }

  /**
   * Resizes canvases to fit their CSS container cleanly with HiDPI crispness.
   */
  resize(containerWidth, containerHeight) {
    this.dpr = Math.min(window.devicePixelRatio || 1, 3);
    const vw = window.innerWidth || containerWidth;
    const isCompactMobile = vw < 600;

    // Side mini canvases scale first so we know exact width available for the main board
    const miniCell = isCompactMobile
      ? Math.max(9, Math.min(12, Math.floor(vw / 34)))
      : Math.max(13, Math.min(20, Math.floor(containerHeight / 28)));
    this.miniCellSize = miniCell;

    const holdW = Math.round(miniCell * 4.2);
    const holdH = Math.round(miniCell * 3.0);
    const nextW = Math.round(miniCell * 4.2);
    const nextH = Math.round(miniCell * 14.2);

    if (this.holdCanvas && this.holdCtx) {
      this._setupHiDPICanvas(this.holdCanvas, this.holdCtx, holdW, holdH);
    }

    if (this.nextCanvas && this.nextCtx) {
      this._setupHiDPICanvas(this.nextCanvas, this.nextCtx, nextW, nextH);
    }

    // Reserve space for left (Hold) + right (Next) panels + gaps
    const sidePanelsWidth = holdW + nextW + (isCompactMobile ? 34 : 56);
    const usableBoardWidth = Math.max(140, Math.min(containerWidth, vw - sidePanelsWidth));
    const usableBoardHeight = Math.max(240, containerHeight - 8);

    // Compute largest integer cellSize that fits 10x20 inside usable area
    const maxCellW = Math.floor(usableBoardWidth / BOARD_WIDTH);
    const maxCellH = Math.floor(usableBoardHeight / VISIBLE_ROWS);
    const newCellSize = Math.max(13, Math.min(maxCellW, maxCellH));

    if (newCellSize !== this.cellSize) {
      this.cellSize = newCellSize;
      this.spriteCache.clear();
    }

    this.boardWidthPx = BOARD_WIDTH * this.cellSize;
    this.boardHeightPx = VISIBLE_ROWS * this.cellSize;

    this._setupHiDPICanvas(this.boardCanvas, this.boardCtx, this.boardWidthPx, this.boardHeightPx);

    if (this.bgCanvas && this.bgCtx) {
      this._setupHiDPICanvas(
        this.bgCanvas,
        this.bgCtx,
        window.innerWidth,
        window.innerHeight
      );
    }
  }

  _setupHiDPICanvas(canvas, ctx, cssWidth, cssHeight) {
    const w = Math.round(cssWidth);
    const h = Math.round(cssHeight);
    canvas.style.width = `${w}px`;
    canvas.style.height = `${h}px`;
    canvas.width = Math.round(w * this.dpr);
    canvas.height = Math.round(h * this.dpr);
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
  }

  /**
   * Returns a cached offscreen canvas containing a glossy/bevelled block sprite.
   */
  _getBlockSprite(color, size) {
    const key = `${color}_${size}_${this.settings.theme}_${this.dpr}`;
    const cached = this.spriteCache.get(key);
    if (cached) return cached;

    const offscreen = document.createElement('canvas');
    offscreen.width = Math.ceil(size * this.dpr);
    offscreen.height = Math.ceil(size * this.dpr);
    const ctx = offscreen.getContext('2d');
    ctx.scale(this.dpr, this.dpr);

    const pad = 1;
    const inner = size - pad * 2;
    const r = Math.max(2, size * 0.14);

    // Base fill
    ctx.fillStyle = color;
    this._roundRect(ctx, pad, pad, inner, inner, r);
    ctx.fill();

    if (this.settings.theme !== 'minimal') {
      // Top-left glossy highlight bevel
      const grad = ctx.createLinearGradient(pad, pad, pad, pad + inner);
      grad.addColorStop(0, 'rgba(255, 255, 255, 0.42)');
      grad.addColorStop(0.45, 'rgba(255, 255, 255, 0.06)');
      grad.addColorStop(1, 'rgba(0, 0, 0, 0.34)');
      ctx.fillStyle = grad;
      this._roundRect(ctx, pad, pad, inner, inner, r);
      ctx.fill();

      // Inner jewel specularity
      const inset = Math.max(3, size * 0.2);
      ctx.fillStyle = 'rgba(255, 255, 255, 0.16)';
      this._roundRect(
        ctx,
        inset,
        inset,
        size - inset * 2,
        (size - inset * 2) * 0.5,
        Math.max(1, r * 0.5)
      );
      ctx.fill();

      // Crisp border
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.28)';
      ctx.lineWidth = 1;
      this._roundRect(ctx, pad + 0.5, pad + 0.5, inner - 1, inner - 1, r);
      ctx.stroke();
    } else {
      // Minimal flat style with subtle inner border
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.22)';
      ctx.lineWidth = 1.2;
      this._roundRect(ctx, pad + 0.5, pad + 0.5, inner - 1, inner - 1, r);
      ctx.stroke();
    }

    this.spriteCache.set(key, offscreen);
    return offscreen;
  }

  _roundRect(ctx, x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  /**
   * Draws a single cell at board coordinates (col, visibleRow).
   */
  _drawCell(ctx, col, visRow, color, size, alpha = 1, pieceType = null) {
    if (visRow < 0 || visRow >= VISIBLE_ROWS) return;
    const sprite = this._getBlockSprite(color, size);
    const px = col * size;
    const py = visRow * size;

    ctx.save();
    if (alpha < 1) ctx.globalAlpha = alpha;
    ctx.drawImage(sprite, px, py, size, size);

    // Optional colorblind symbol overlay so pieces are distinguishable even without color
    if (this.settings.colorblind && pieceType) {
      ctx.fillStyle = 'rgba(0, 0, 0, 0.55)';
      ctx.font = `bold ${Math.max(9, Math.round(size * 0.42))}px monospace`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(pieceType, px + size * 0.5, py + size * 0.52);
    }
    ctx.restore();
  }

  /**
   * Renders the subtle animated background starfield.
   */
  renderBackground(dtMs, level = 1) {
    if (!this.bgCtx || !this.bgCanvas) return;
    const ctx = this.bgCtx;
    const w = this.bgCanvas.width / this.dpr;
    const h = this.bgCanvas.height / this.dpr;

    ctx.clearRect(0, 0, w, h);

    if (this.settings.reducedMotion) return;

    const speedFactor = (1 + (level - 1) * 0.18) * (dtMs / 16.67);
    ctx.fillStyle = this.settings.theme === 'minimal'
      ? 'rgba(100, 116, 139, 0.25)'
      : 'rgba(148, 210, 255, 0.45)';

    for (let i = 0; i < this.stars.length; i++) {
      const s = this.stars[i];
      s.y += s.speed * 0.015 * speedFactor;
      s.phase += 0.03 * speedFactor;
      if (s.y > 1) {
        s.y = 0;
        s.x = Math.random();
      }
      const alpha = 0.25 + 0.45 * Math.sin(s.phase);
      ctx.globalAlpha = Math.max(0.1, alpha);
      ctx.beginPath();
      ctx.arc(s.x * w, s.y * h, s.size, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  /**
   * Main render method called each animation frame.
   */
  render(game, dtMs) {
    const ctx = this.boardCtx;
    const cs = this.cellSize;
    const w = this.boardWidthPx;
    const h = this.boardHeightPx;

    ctx.save();

    // Board background fill
    ctx.fillStyle = this.settings.theme === 'minimal' ? '#f8fafc' : '#080b16';
    ctx.fillRect(0, 0, w, h);

    // Apply screen shake offset
    if (this.effects && (this.effects.shakeOffsetX !== 0 || this.effects.shakeOffsetY !== 0)) {
      ctx.translate(this.effects.shakeOffsetX, this.effects.shakeOffsetY);
    }

    // Subtle grid lines
    if (this.settings.grid) {
      ctx.strokeStyle =
        this.settings.theme === 'minimal'
          ? 'rgba(15, 23, 42, 0.07)'
          : 'rgba(148, 163, 184, 0.08)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      for (let x = 1; x < BOARD_WIDTH; x++) {
        ctx.moveTo(x * cs + 0.5, 0);
        ctx.lineTo(x * cs + 0.5, h);
      }
      for (let y = 1; y < VISIBLE_ROWS; y++) {
        ctx.moveTo(0, y * cs + 0.5);
        ctx.lineTo(w, y * cs + 0.5);
      }
      ctx.stroke();
    }

    // Underlay effects (hard drop light beams, row flashes)
    if (this.effects) {
      this.effects.renderUnderlay(ctx, cs, w);
    }

    // Locked board cells
    const isGameOver = game.state === 'GAME_OVER';
    if (isGameOver) {
      this.gameOverAnim = Math.min(1, this.gameOverAnim + dtMs / 900);
    } else {
      this.gameOverAnim = 0;
    }

    const collapseRowCutoff = isGameOver
      ? Math.floor((1 - this.gameOverAnim) * VISIBLE_ROWS)
      : VISIBLE_ROWS;

    for (let y = HIDDEN_ROWS; y < TOTAL_ROWS; y++) {
      const visRow = y - HIDDEN_ROWS;
      for (let x = 0; x < BOARD_WIDTH; x++) {
        const cell = game.board.grid[y][x];
        if (!cell) continue;
        const color = isGameOver && visRow >= collapseRowCutoff ? '#475569' : cell.color;
        this._drawCell(ctx, x, visRow, color, cs, 1, cell.type);
      }
    }

    // Ghost piece & Active piece
    const active = game.activePiece;
    if (active && game.state !== 'GAME_OVER') {
      const matrix = SHAPES[active.type][active.rotation];

      // Ghost piece
      if (this.settings.ghost) {
        const ghostY = game.getGhostY();
        if (ghostY > active.y) {
          ctx.save();
          for (let r = 0; r < matrix.length; r++) {
            for (let c = 0; c < matrix[r].length; c++) {
              if (!matrix[r][c]) continue;
              const gx = active.x + c;
              const gy = ghostY + r - HIDDEN_ROWS;
              if (gy < 0 || gy >= VISIBLE_ROWS) continue;

              const px = gx * cs + 2;
              const py = gy * cs + 2;
              const inner = cs - 4;
              ctx.fillStyle = active.color;
              ctx.globalAlpha = 0.16;
              this._roundRect(ctx, px, py, inner, inner, 3);
              ctx.fill();

              ctx.globalAlpha = 0.58;
              ctx.strokeStyle = active.color;
              ctx.lineWidth = 1.5;
              ctx.stroke();
            }
          }
          ctx.restore();
        }
      }

      // Active piece with lock-delay pulse feedback
      let lockAlpha = 1;
      if (game.lockTimerMs > 0) {
        const lockProgress = Math.min(1, game.lockTimerMs / LOCK_DELAY_MS);
        lockAlpha = 1 - lockProgress * 0.32;
      }

      for (let r = 0; r < matrix.length; r++) {
        for (let c = 0; c < matrix[r].length; c++) {
          if (!matrix[r][c]) continue;
          const px = active.x + c;
          const py = active.y + r - HIDDEN_ROWS;
          this._drawCell(ctx, px, py, active.color, cs, lockAlpha, active.type);
        }
      }
    }

    // Overlay effects (particles, lock flashes, callouts, level pulse)
    if (this.effects) {
      this.effects.renderOverlay(ctx, cs, w, h);
    }

    ctx.restore();

    // Render Hold & Next-5 mini canvases
    this._renderHold(game);
    this._renderNextQueue(game);
  }

  _renderHold(game) {
    if (!this.holdCtx || !this.holdCanvas) return;
    const ctx = this.holdCtx;
    const w = this.holdCanvas.width / this.dpr;
    const h = this.holdCanvas.height / this.dpr;
    ctx.clearRect(0, 0, w, h);

    if (!game.holdPieceType) return;

    const color = game.canHold
      ? game.colorMap[game.holdPieceType]
      : '#64748b';
    this._drawMiniPiece(ctx, game.holdPieceType, color, w * 0.5, h * 0.5, this.miniCellSize);
  }

  _renderNextQueue(game) {
    if (!this.nextCtx || !this.nextCanvas) return;
    const ctx = this.nextCtx;
    const w = this.nextCanvas.width / this.dpr;
    const h = this.nextCanvas.height / this.dpr;
    ctx.clearRect(0, 0, w, h);

    const queue = game.getNextQueue(5);
    const slotHeight = h / 5;

    for (let i = 0; i < queue.length; i++) {
      const type = queue[i];
      const color = game.colorMap[type] || '#00e5ff';
      const scale = i === 0 ? 1.0 : 0.88;
      this._drawMiniPiece(
        ctx,
        type,
        color,
        w * 0.5,
        slotHeight * (i + 0.5),
        Math.round(this.miniCellSize * scale)
      );
    }
  }

  _drawMiniPiece(ctx, type, color, centerX, centerY, cellSize) {
    const matrix = SHAPES[type][0];
    let minR = 4, maxR = -1, minC = 4, maxC = -1;
    for (let r = 0; r < matrix.length; r++) {
      for (let c = 0; c < matrix[r].length; c++) {
        if (matrix[r][c]) {
          if (r < minR) minR = r;
          if (r > maxR) maxR = r;
          if (c < minC) minC = c;
          if (c > maxC) maxC = c;
        }
      }
    }

    const pieceW = (maxC - minC + 1) * cellSize;
    const pieceH = (maxR - minR + 1) * cellSize;
    const startX = centerX - pieceW * 0.5;
    const startY = centerY - pieceH * 0.5;

    const sprite = this._getBlockSprite(color, cellSize);
    for (let r = minR; r <= maxR; r++) {
      for (let c = minC; c <= maxC; c++) {
        if (!matrix[r][c]) continue;
        const x = startX + (c - minC) * cellSize;
        const y = startY + (r - minR) * cellSize;
        ctx.drawImage(sprite, x, y, cellSize, cellSize);
      }
    }
  }
}

// ===== src/input/keyboard.js =====
// src/input/keyboard.js
// Desktop keyboard input controller with configurable DAS (Delayed Auto Shift),
// ARR (Auto Repeat Rate), and customizable key bindings.

const DEFAULT_KEY_BINDINGS = Object.freeze({
  moveLeft: 'ArrowLeft',
  moveRight: 'ArrowRight',
  softDrop: 'ArrowDown',
  hardDrop: 'Space',
  rotateCW: 'ArrowUp',
  rotateCCW: 'KeyZ',
  rotate180: 'KeyA',
  hold: 'KeyC',
  pause: 'Escape',
  restart: 'KeyR',
});

// Secondary convenience aliases that always work alongside primary bindings
const SECONDARY_ALIASES = Object.freeze({
  moveLeft: ['KeyJ'],
  moveRight: ['KeyL'],
  softDrop: ['KeyK'],
  rotateCW: ['KeyX'],
  rotateCCW: ['ControlLeft', 'ControlRight'],
  hold: ['ShiftLeft', 'ShiftRight'],
  pause: ['KeyP'],
});

class KeyboardInput {
  constructor({ onAction, settings = {} }) {
    this.onAction = onAction;
    this.das = settings.das ?? 167;
    this.arr = settings.arr ?? 33;
    this.bindings = { ...DEFAULT_KEY_BINDINGS, ...(settings.keyBindings || {}) };

    this.enabled = true;
    this.isRebinding = false;
    this.onRebindCapture = null;

    // Horizontal movement state for DAS/ARR
    this.leftHeld = false;
    this.rightHeld = false;
    this.activeDir = 0; // -1 left, 1 right, 0 none
    this.dasTimerMs = 0;
    this.arrTimerMs = 0;

    // Soft drop state
    this.softDropHeld = false;

    this._handleKeyDown = this._handleKeyDown.bind(this);
    this._handleKeyUp = this._handleKeyUp.bind(this);
    this._handleBlur = this._handleBlur.bind(this);

    window.addEventListener('keydown', this._handleKeyDown);
    window.addEventListener('keyup', this._handleKeyUp);
    window.addEventListener('blur', this._handleBlur);
  }

  updateSettings(partial = {}) {
    if (typeof partial.das === 'number') this.das = partial.das;
    if (typeof partial.arr === 'number') this.arr = partial.arr;
    if (partial.keyBindings) {
      this.bindings = { ...DEFAULT_KEY_BINDINGS, ...partial.keyBindings };
    }
  }

  startRebind(callback) {
    this.isRebinding = true;
    this.onRebindCapture = callback;
  }

  cancelRebind() {
    this.isRebinding = false;
    this.onRebindCapture = null;
  }

  _matchesAction(code, action) {
    if (this.bindings[action] === code) return true;
    const aliases = SECONDARY_ALIASES[action];
    if (aliases && aliases.includes(code)) {
      // Only use alias if it isn't explicitly bound to another primary action
      const boundElsewhere = Object.entries(this.bindings).some(
        ([k, v]) => k !== action && v === code
      );
      return !boundElsewhere;
    }
    return false;
  }

  _isTypingInInput(event) {
    const tag = event.target && event.target.tagName;
    return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT';
  }

  _handleKeyDown(event) {
    if (this._isTypingInInput(event)) return;

    if (this.isRebinding && this.onRebindCapture) {
      event.preventDefault();
      const code = event.code;
      const cb = this.onRebindCapture;
      this.isRebinding = false;
      this.onRebindCapture = null;
      cb(code);
      return;
    }

    if (!this.enabled) return;

    const code = event.code;

    // Prevent browser scrolling on game keys
    if (
      ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Space'].includes(code)
    ) {
      event.preventDefault();
    }

    if (event.repeat) return;

    if (this._matchesAction(code, 'moveLeft')) {
      this.leftHeld = true;
      this.activeDir = -1;
      this.dasTimerMs = 0;
      this.arrTimerMs = 0;
      this.onAction('moveLeft');
    } else if (this._matchesAction(code, 'moveRight')) {
      this.rightHeld = true;
      this.activeDir = 1;
      this.dasTimerMs = 0;
      this.arrTimerMs = 0;
      this.onAction('moveRight');
    } else if (this._matchesAction(code, 'softDrop')) {
      this.softDropHeld = true;
    } else if (this._matchesAction(code, 'hardDrop')) {
      this.onAction('hardDrop');
    } else if (this._matchesAction(code, 'rotateCW')) {
      this.onAction('rotateCW');
    } else if (this._matchesAction(code, 'rotateCCW')) {
      this.onAction('rotateCCW');
    } else if (this._matchesAction(code, 'rotate180')) {
      this.onAction('rotate180');
    } else if (this._matchesAction(code, 'hold')) {
      this.onAction('hold');
    } else if (this._matchesAction(code, 'pause')) {
      this.onAction('pause');
    } else if (this._matchesAction(code, 'restart')) {
      this.onAction('restart');
    }
  }

  _handleKeyUp(event) {
    const code = event.code;
    if (this._matchesAction(code, 'moveLeft')) {
      this.leftHeld = false;
      if (this.rightHeld) {
        this.activeDir = 1;
        this.dasTimerMs = 0;
        this.arrTimerMs = 0;
      } else if (this.activeDir === -1) {
        this.activeDir = 0;
      }
    } else if (this._matchesAction(code, 'moveRight')) {
      this.rightHeld = false;
      if (this.leftHeld) {
        this.activeDir = -1;
        this.dasTimerMs = 0;
        this.arrTimerMs = 0;
      } else if (this.activeDir === 1) {
        this.activeDir = 0;
      }
    } else if (this._matchesAction(code, 'softDrop')) {
      this.softDropHeld = false;
    }
  }

  _handleBlur() {
    this.resetState();
  }

  resetState() {
    this.leftHeld = false;
    this.rightHeld = false;
    this.activeDir = 0;
    this.dasTimerMs = 0;
    this.arrTimerMs = 0;
    this.softDropHeld = false;
  }

  /**
   * Called once per simulation tick with `dtMs`.
   */
  update(dtMs) {
    if (!this.enabled || this.activeDir === 0) return;

    this.dasTimerMs += dtMs;
    if (this.dasTimerMs < this.das) return;

    const action = this.activeDir === -1 ? 'moveLeft' : 'moveRight';

    if (this.arr <= 0) {
      // Instant ARR (0 ms): shift all the way to the wall
      for (let i = 0; i < 10; i++) {
        this.onAction(action);
      }
      return;
    }

    this.arrTimerMs += dtMs;
    while (this.arrTimerMs >= this.arr) {
      this.arrTimerMs -= this.arr;
      this.onAction(action);
    }
  }

  destroy() {
    window.removeEventListener('keydown', this._handleKeyDown);
    window.removeEventListener('keyup', this._handleKeyUp);
    window.removeEventListener('blur', this._handleBlur);
  }
}

// ===== src/input/gamepad.js =====
// src/input/gamepad.js
// Standard Gamepad API polling controller with DAS/ARR support.

class GamepadInput {
  constructor({ onAction, settings = {} }) {
    this.onAction = onAction;
    this.das = settings.das ?? 167;
    this.arr = settings.arr ?? 33;
    this.enabled = true;

    this.prevButtons = new Map();
    this.activeDir = 0;
    this.dasTimerMs = 0;
    this.arrTimerMs = 0;
    this.softDropHeld = false;
  }

  updateSettings(partial = {}) {
    if (typeof partial.das === 'number') this.das = partial.das;
    if (typeof partial.arr === 'number') this.arr = partial.arr;
  }

  update(dtMs) {
    if (!this.enabled || typeof navigator.getGamepads !== 'function') return;

    const pads = navigator.getGamepads();
    let pad = null;
    for (let i = 0; i < pads.length; i++) {
      if (pads[i] && pads[i].connected) {
        pad = pads[i];
        break;
      }
    }
    if (!pad) {
      this.softDropHeld = false;
      this.activeDir = 0;
      return;
    }

    const isPressed = (idx) => Boolean(pad.buttons[idx] && pad.buttons[idx].pressed);
    const justPressed = (idx) => isPressed(idx) && !this.prevButtons.get(idx);

    // Standard Gamepad mapping:
    // 0 (A/Cross): Rotate CW
    // 1 (B/Circle): Rotate CCW
    // 2 (X/Square): Rotate 180
    // 3 (Y/Triangle) or 4 (LB) or 5 (RB): Hold
    // 12 (D-Up): Hard Drop
    // 13 (D-Down): Soft Drop
    // 14 (D-Left): Move Left
    // 15 (D-Right): Move Right
    // 9 (Start): Pause
    // 8 (Select/Back): Restart

    if (justPressed(0)) this.onAction('rotateCW');
    if (justPressed(1)) this.onAction('rotateCCW');
    if (justPressed(2)) this.onAction('rotate180');
    if (justPressed(3) || justPressed(4) || justPressed(5)) this.onAction('hold');
    if (justPressed(12)) this.onAction('hardDrop');
    if (justPressed(9)) this.onAction('pause');
    if (justPressed(8)) this.onAction('restart');

    const axisX = pad.axes[0] || 0;
    const axisY = pad.axes[1] || 0;

    const leftDown = isPressed(14) || axisX < -0.45;
    const rightDown = isPressed(15) || axisX > 0.45;
    this.softDropHeld = isPressed(13) || axisY > 0.5;

    const newDir = leftDown ? -1 : rightDown ? 1 : 0;
    if (newDir !== this.activeDir) {
      this.activeDir = newDir;
      this.dasTimerMs = 0;
      this.arrTimerMs = 0;
      if (newDir === -1) this.onAction('moveLeft');
      else if (newDir === 1) this.onAction('moveRight');
    } else if (this.activeDir !== 0) {
      this.dasTimerMs += dtMs;
      if (this.dasTimerMs >= this.das) {
        this.arrTimerMs += dtMs;
        const stepArr = Math.max(16, this.arr);
        while (this.arrTimerMs >= stepArr) {
          this.arrTimerMs -= stepArr;
          this.onAction(this.activeDir === -1 ? 'moveLeft' : 'moveRight');
        }
      }
    }

    // Store button states for edge detection
    for (let i = 0; i < pad.buttons.length; i++) {
      this.prevButtons.set(i, isPressed(i));
    }
  }
}

// ===== src/input/touch.js =====
// src/input/touch.js
// Mobile-first touch input controller supporting:
// 1. Direct board gestures (Tap = CW, 2-finger tap = CCW, Horizontal drag = proportional column shift,
//    Slow downward drag = soft drop, Fast downward flick = hard drop, Swipe up = hold)
// 2. Ergonomic on-screen thumb buttons with DAS/ARR repeat, button size, and left-handed layout
// 3. Haptic feedback via navigator.vibrate

class TouchInput {
  constructor({ boardElement, holdElement, buttonsContainer, onAction, settings = {} }) {
    this.boardElement = boardElement;
    this.holdElement = holdElement;
    this.buttonsContainer = buttonsContainer;
    this.onAction = onAction;

    this.settings = {
      touchScheme: 'both', // 'gestures' | 'buttons' | 'both'
      touchSensitivity: 1.0, // 0.5 .. 1.8 multiplier
      buttonSize: 'medium', // 'small' | 'medium' | 'large'
      leftHanded: false,
      haptics: true,
      das: 167,
      arr: 33,
      ...settings,
    };

    this.enabled = true;
    this.softDropHeld = false;

    // Active gesture tracking state
    this.primaryTouchId = null;
    this.startX = 0;
    this.startY = 0;
    this.lastX = 0;
    this.lastY = 0;
    this.accumulatedX = 0;
    this.accumulatedY = 0;
    this.startTime = 0;
    this.lastMoveTime = 0;
    this.velocityY = 0;
    this.movedHorizontally = false;
    this.movedVertically = false;
    this.gestureConsumed = false;
    this.maxConcurrentTouches = 0;

    // On-screen button repeat state
    this.heldButtonDir = 0; // -1 left, 1 right
    this.dasTimerMs = 0;
    this.arrTimerMs = 0;

    this._bindEvents();
    this._applyLayoutSettings();
  }

  updateSettings(partial = {}) {
    this.settings = { ...this.settings, ...partial };
    this._applyLayoutSettings();
  }

  _applyLayoutSettings() {
    if (!this.buttonsContainer) return;
    const scheme = this.settings.touchScheme || 'both';
    this.buttonsContainer.dataset.scheme = scheme;
    this.buttonsContainer.dataset.size = this.settings.buttonSize || 'medium';
    this.buttonsContainer.dataset.handed = this.settings.leftHanded ? 'left' : 'right';
  }

  vibrate(pattern = 10) {
    if (!this.settings.haptics) return;
    try {
      if (typeof navigator !== 'undefined' && typeof navigator.vibrate === 'function') {
        navigator.vibrate(pattern);
      }
    } catch {
      // Ignore vibration errors on unsupported browsers
    }
  }

  _bindEvents() {
    if (this.boardElement) {
      this.boardElement.addEventListener('touchstart', (e) => this._onTouchStart(e), {
        passive: false,
      });
      this.boardElement.addEventListener('touchmove', (e) => this._onTouchMove(e), {
        passive: false,
      });
      this.boardElement.addEventListener('touchend', (e) => this._onTouchEnd(e), {
        passive: false,
      });
      this.boardElement.addEventListener('touchcancel', () => this.resetState(), {
        passive: false,
      });
    }

    // Tap on Hold box triggers hold
    if (this.holdElement) {
      this.holdElement.addEventListener('pointerdown', (e) => {
        if (!this.enabled) return;
        e.preventDefault();
        this.vibrate(14);
        this.onAction('hold');
      });
    }

    // Bind virtual thumb buttons using Pointer Events for zero-delay multi-touch safety
    if (this.buttonsContainer) {
      const buttons = this.buttonsContainer.querySelectorAll('[data-touch-action]');
      buttons.forEach((btn) => {
        const action = btn.getAttribute('data-touch-action');

        btn.addEventListener('pointerdown', (e) => {
          if (!this.enabled) return;
          e.preventDefault();
          btn.classList.add('is-active');
          try {
            btn.setPointerCapture(e.pointerId);
          } catch {
            // ignore
          }
          this._onVirtualButtonDown(action);
        });

        const release = (e) => {
          e.preventDefault();
          btn.classList.remove('is-active');
          this._onVirtualButtonUp(action);
        };

        btn.addEventListener('pointerup', release);
        btn.addEventListener('pointercancel', release);
        btn.addEventListener('lostpointercapture', release);
      });
    }

    window.addEventListener('blur', () => this.resetState());
  }

  _onVirtualButtonDown(action) {
    if (action === 'moveLeft') {
      this.heldButtonDir = -1;
      this.dasTimerMs = 0;
      this.arrTimerMs = 0;
      this.vibrate(8);
      this.onAction('moveLeft');
    } else if (action === 'moveRight') {
      this.heldButtonDir = 1;
      this.dasTimerMs = 0;
      this.arrTimerMs = 0;
      this.vibrate(8);
      this.onAction('moveRight');
    } else if (action === 'softDrop') {
      this.softDropHeld = true;
      this.vibrate(8);
      this.onAction('softDropStep');
    } else if (action === 'hardDrop') {
      this.vibrate([18, 25, 18]);
      this.onAction('hardDrop');
    } else if (action === 'rotateCW') {
      this.vibrate(10);
      this.onAction('rotateCW');
    } else if (action === 'rotateCCW') {
      this.vibrate(10);
      this.onAction('rotateCCW');
    } else if (action === 'hold') {
      this.vibrate(14);
      this.onAction('hold');
    }
  }

  _onVirtualButtonUp(action) {
    if (action === 'moveLeft' && this.heldButtonDir === -1) {
      this.heldButtonDir = 0;
    } else if (action === 'moveRight' && this.heldButtonDir === 1) {
      this.heldButtonDir = 0;
    } else if (action === 'softDrop') {
      this.softDropHeld = false;
    }
  }

  _getStepPx() {
    const rect = this.boardElement.getBoundingClientRect();
    const baseColWidth = Math.max(20, rect.width / 10);
    const sens = Math.max(0.4, Math.min(2.0, Number(this.settings.touchSensitivity) || 1.0));
    return baseColWidth / sens;
  }

  _onTouchStart(e) {
    if (!this.enabled || this.settings.touchScheme === 'buttons') return;
    e.preventDefault();

    this.maxConcurrentTouches = Math.max(this.maxConcurrentTouches, e.touches.length);

    if (e.touches.length === 2) {
      // Two-finger tap on the board rotates counter-clockwise immediately
      this.gestureConsumed = true;
      this.vibrate(12);
      this.onAction('rotateCCW');
      return;
    }

    if (this.primaryTouchId === null && e.changedTouches.length > 0) {
      const t = e.changedTouches[0];
      this.primaryTouchId = t.identifier;
      this.startX = t.clientX;
      this.startY = t.clientY;
      this.lastX = t.clientX;
      this.lastY = t.clientY;
      this.accumulatedX = 0;
      this.accumulatedY = 0;
      this.startTime = performance.now();
      this.lastMoveTime = this.startTime;
      this.velocityY = 0;
      this.movedHorizontally = false;
      this.movedVertically = false;
      this.gestureConsumed = false;
      this.maxConcurrentTouches = 1;
    }
  }

  _onTouchMove(e) {
    if (
      !this.enabled ||
      this.settings.touchScheme === 'buttons' ||
      this.primaryTouchId === null ||
      this.gestureConsumed
    ) {
      return;
    }
    e.preventDefault();

    let touch = null;
    for (let i = 0; i < e.changedTouches.length; i++) {
      if (e.changedTouches[i].identifier === this.primaryTouchId) {
        touch = e.changedTouches[i];
        break;
      }
    }
    if (!touch) return;

    const now = performance.now();
    const dt = Math.max(1, now - this.lastMoveTime);
    const dx = touch.clientX - this.lastX;
    const dy = touch.clientY - this.lastY;

    this.velocityY = dy / dt; // px per ms
    this.lastX = touch.clientX;
    this.lastY = touch.clientY;
    this.lastMoveTime = now;

    const totalDx = touch.clientX - this.startX;
    const totalDy = touch.clientY - this.startY;
    const stepPx = this._getStepPx();

    // Check upward swipe for Hold piece
    if (
      !this.movedHorizontally &&
      !this.movedVertically &&
      totalDy < -stepPx * 1.65 &&
      Math.abs(totalDy) > Math.abs(totalDx) * 1.5
    ) {
      this.gestureConsumed = true;
      this.vibrate(14);
      this.onAction('hold');
      return;
    }

    // Horizontal proportional column dragging (suppress during steep vertical flick)
    const isSteepVertical = Math.abs(dy) > Math.abs(dx) * 2.2 && this.velocityY > 0.9;
    if (!isSteepVertical) {
      this.accumulatedX += dx;
      while (Math.abs(this.accumulatedX) >= stepPx) {
        if (this.accumulatedX > 0) {
          this.accumulatedX -= stepPx;
          this.movedHorizontally = true;
          this.vibrate(6);
          this.onAction('moveRight');
        } else {
          this.accumulatedX += stepPx;
          this.movedHorizontally = true;
          this.vibrate(6);
          this.onAction('moveLeft');
        }
      }
    }

    // Slow downward drag -> soft drop steps
    if (dy > 0 && this.velocityY < 1.15) {
      this.accumulatedY += dy;
      const dropStepPx = stepPx * 0.85;
      while (this.accumulatedY >= dropStepPx) {
        this.accumulatedY -= dropStepPx;
        this.movedVertically = true;
        this.onAction('softDropStep');
      }
    }
  }

  _onTouchEnd(e) {
    if (!this.enabled || this.settings.touchScheme === 'buttons') return;
    e.preventDefault();

    let endedPrimary = null;
    for (let i = 0; i < e.changedTouches.length; i++) {
      if (e.changedTouches[i].identifier === this.primaryTouchId) {
        endedPrimary = e.changedTouches[i];
        break;
      }
    }
    if (!endedPrimary) return;

    const now = performance.now();
    const duration = Math.max(1, now - this.startTime);
    const totalDx = endedPrimary.clientX - this.startX;
    const totalDy = endedPrimary.clientY - this.startY;
    const overallVy = totalDy / duration;

    if (!this.gestureConsumed && this.maxConcurrentTouches === 1) {
      // Check fast downward flick -> Hard Drop
      if (
        totalDy > 38 &&
        Math.abs(totalDy) > Math.abs(totalDx) * 1.35 &&
        (overallVy > 0.65 || this.velocityY > 0.95)
      ) {
        this.vibrate([18, 25, 18]);
        this.onAction('hardDrop');
      } else if (
        // Tap on board -> Rotate Clockwise
        !this.movedHorizontally &&
        !this.movedVertically &&
        Math.hypot(totalDx, totalDy) < 18 &&
        duration < 280
      ) {
        this.vibrate(10);
        this.onAction('rotateCW');
      }
    }

    this.primaryTouchId = null;
    if (e.touches.length === 0) {
      this.maxConcurrentTouches = 0;
    }
  }

  resetState() {
    this.primaryTouchId = null;
    this.heldButtonDir = 0;
    this.softDropHeld = false;
    this.dasTimerMs = 0;
    this.arrTimerMs = 0;
    this.gestureConsumed = false;
  }

  update(dtMs) {
    if (!this.enabled || this.heldButtonDir === 0) return;

    this.dasTimerMs += dtMs;
    if (this.dasTimerMs < this.settings.das) return;

    const action = this.heldButtonDir === -1 ? 'moveLeft' : 'moveRight';
    const arr = Math.max(16, this.settings.arr);
    this.arrTimerMs += dtMs;
    while (this.arrTimerMs >= arr) {
      this.arrTimerMs -= arr;
      this.vibrate(5);
      this.onAction(action);
    }
  }
}

